def test_get_job_timeseries_future_dates_handling(api_client, swagger_validator, endpoint_path_str, endpoint_test_data, config_test_data):
    """
    Edge: Shift provided date range into the future to probe retention/validation behavior.
    The test asserts deviation from the success code when future dates are used.
    If the API returns 200 (e.g., empty set), validate against success schema.
    Otherwise, validate default error schema.
    """
    from datetime import datetime, timedelta, timezone

    def parse_utc(dt_str: str) -> Optional[datetime]:
        try:
            # Format: 2025-09-01T00:00:00Z
            return datetime.strptime(dt_str, "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc)
        except Exception:
            return None

    ran_any = False
    for case in endpoint_test_data:
        start = case.get("start-date")
        end = case.get("end-date")
        # Need both dates to shift range coherently
        if not start or not end:
            continue

        start_dt = parse_utc(start)
        end_dt = parse_utc(end)
        if not start_dt or not end_dt:
            # Skip unparseable dates from scenario; do not hardcode alternatives
            continue

        future_offset_days = 365
        future_start = (start_dt + timedelta(days=future_offset_days)).strftime("%Y-%m-%dT%H:%M:%SZ")
        future_end = (end_dt + timedelta(days=future_offset_days)).strftime("%Y-%m-%dT%H:%M:%SZ")

        project_slug, workflow_name = _required_from(case, config_test_data)
        _assert_required_present_or_skip(project_slug, workflow_name)
        endpoint = _build_endpoint(project_slug, workflow_name)

        params = _optional_query_from(case)
        params["start-date"] = future_start
        params["end-date"] = future_end

        resp = api_client.get(endpoint, params=params if params else None)

        expected_success = int(case.get("statusCode", 200))
        if resp.status_code == expected_success:
            _validate_response(swagger_validator, endpoint_path_str, "get", "200", resp)
        else:
            _validate_response(swagger_validator, endpoint_path_str, "get", "default", resp)
        ran_any = True

    if not ran_any:
        pytest.skip("No scenarios with valid start-date and end-date to exercise future date handling.")
